  <style>
    :root{
      --sat: env(safe-area-inset-top, 0px);
      --sar: env(safe-area-inset-right, 0px);
      --sab: env(safe-area-inset-bottom, 0px);
      --sal: env(safe-area-inset-left, 0px);
      --blue:#0071e3;
      --blue-l:#147CE5;
      --surface: rgba(16,16,18,.78);
      --surface-hi: rgba(255,255,255,.055);
      --border: rgba(255,255,255,.08);
      --border-s: rgba(255,255,255,.05);
      --fg:#f5f5f7;
      --fg2: rgba(245,245,247,.5);
      --fg3: rgba(245,245,247,.25);
      --acc:#0071e3;
      --accent:#0071e3;
      --glass: rgba(20,20,24,.72);
      --bg: rgba(10,10,14,.97);
      --hover: rgba(255,255,255,.07);
      --user-bg:#0071e3;
      --ai-bg: rgba(28,28,32,.95);
      --ai-fg:#f5f5f7;
      --rc-bg: rgba(26,26,30,.85);
      --input-bg: rgba(255,255,255,.07);
      --input-border: rgba(255,255,255,.07);
      --sep: rgba(255,255,255,.06);
      --liquid-glass: rgba(255,255,255,.085);
      --liquid-border: rgba(255,255,255,.28);
      --liquid-shadow: 0 8px 32px -4px rgba(0,113,227,.28);
      --glow: rgba(0,113,227,.22);
    }
    @media (prefers-color-scheme: light){
      :root{
        --surface: rgba(248,248,250,.82);
        --surface-hi: rgba(255,255,255,.9);
        --border: rgba(0,0,0,.07);
        --border-s: rgba(0,0,0,.04);
        --fg:#1d1d1f;
        --fg2: rgba(29,29,31,.5);
        --fg3: rgba(29,29,31,.26);
        --bg: rgba(245,245,247,.97);
        --hover: rgba(0,0,0,.06);
        --ai-bg: rgba(242,242,247,.96);
        --ai-fg:#1d1d1f;
        --rc-bg: rgba(238,238,244,.9);
        --input-bg: rgba(0,0,0,.05);
        --input-border: rgba(0,0,0,.07);
        --sep: rgba(0,0,0,.06);
        --liquid-glass: rgba(245,245,247,.88);
        --liquid-border: rgba(0,0,0,.14);
        --liquid-shadow: 0 8px 32px -4px rgba(0,113,227,.16);
        --glow: rgba(0,113,227,.18);
      }
    }
    *,*::before,*::after{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
    html,body{user-select:none;-webkit-touch-callout:none;height:100%;width:100%;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,'SF Pro Text','SF Pro Display','Helvetica Neue',sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;-webkit-text-size-adjust:100%;overscroll-behavior:none}
    body{background:#000;color:var(--fg)}
    html.standalone body{background:#000}
    input,textarea,[contenteditable="true"],.bubble,.ai-bubble,.bubble *, .ai-bubble *, pre,code,.cb,.cb *, .err-bbl{user-select:text;-webkit-touch-callout:default}
    button,[role="button"],.icon-btn,a,svg{touch-action:manipulation;user-select:none}
    @supports (border-radius:18px){
      .bubble,.ai-bubble,.toast,.ibox,.sb-new,.hcard,.rc-wrap,.srch-bar,.err-bbl,.rcn-bar,.cb{-webkit-mask-image:-webkit-radial-gradient(white,black)}
    }
    #bg{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none}
    .orb{position:absolute;border-radius:50%;filter:blur(110px);will-change:transform;contain:strict;animation:drift var(--d,24s) ease-in-out infinite alternate}
    .o1{width:480px;height:480px;top:-100px;right:-80px;background:radial-gradient(circle, rgba(0,113,227,.12) 0%, transparent 70%);--d:22s}
    .o2{width:360px;height:360px;bottom:12%;left:-100px;background:radial-gradient(circle, rgba(70,70,190,.08) 0%, transparent 70%);--d:29s;animation-direction:alternate-reverse}
    .o3{width:280px;height:280px;bottom:0;right:8%;background:radial-gradient(circle, rgba(0,70,150,.06) 0%, transparent 70%);--d:20s}
    @keyframes drift{0%{transform:translate(0,0) scale(1)}33%{transform:translate(16px,-20px) scale(1.03)}66%{transform:translate(-10px,14px) scale(.97)}100%{transform:translate(20px,8px) scale(1.02)}}
    #app{display:flex;flex-direction:column;height:100vh;min-height:100dvh;width:100%;position:relative;overflow:hidden}
    #sidebar{position:fixed;inset:0;z-index:310;padding-top:var(--sat);background:var(--surface);backdrop-filter:blur(60px) saturate(200%) brightness(92%);display:flex;flex-direction:column;transform:translateX(-100%);transition:transform 420ms cubic-bezier(.32,.72,0,1.18);will-change:transform}
    #sidebar.open{transform:translateX(0)}
    #sidebar.dragging{transition:none}
    .sb-hdr{height:52px;display:flex;align-items:center;padding:0 12px;border-bottom:.5px solid var(--sep);gap:6px}
    .sb-title{flex:1;text-align:center;font-size:15px;font-weight:600;letter-spacing:-.3px}
    .sb-close{width:28px;height:28px;border:0;border-radius:50%;background:var(--input-bg);color:var(--fg);display:grid;place-items:center}
    .sb-close:active{transform:scale(.88);opacity:.7}
    #sb-search-bar{height:0;overflow:hidden;transition:height .32s cubic-bezier(.34,1.28,.64,1)}
    #sb-search-bar.open{height:54px}
    .sb-si{display:flex;align-items:center;gap:8px;background:var(--input-bg);border-radius:13px;border:.5px solid var(--input-border);height:38px;margin:8px 14px 6px;padding:0 12px}
    #sb-q{flex:1;font-size:15px;background:transparent;border:none;outline:none;color:var(--fg)}
    #sb-q-cancel{border:0;background:transparent;font-size:14px;font-weight:500;color:var(--blue-l);width:0;opacity:0;overflow:hidden}
    #sb-q-cancel.open{width:52px;opacity:1}
    .sb-body{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;scrollbar-width:none;padding:12px}
    .sb-pull-hint{font-size:11px;color:var(--fg3);opacity:0;margin-bottom:8px;transition:opacity .2s}
    #sidebar.pull-hinting .sb-pull-hint{opacity:1}
    .sb-new{width:100%;border:0;border-radius:12px;background:rgba(0,113,227,.12);border:.5px solid rgba(0,113,227,.2);font-size:13.5px;font-weight:500;color:var(--blue-l);padding:11px 12px;margin-bottom:12px}
    .sb-new:active{transform:scale(.97);background:rgba(0,113,227,.2)}
    .sb-sec{font-size:11px;font-weight:600;color:var(--fg3);letter-spacing:.5px;text-transform:uppercase;margin:12px 2px 8px}
    .hcard{display:flex;align-items:flex-start;gap:10px;padding:11px 12px;border-radius:12px;margin-bottom:6px;border:.5px solid transparent;transition:transform .22s cubic-bezier(.2,1,.3,1),background .14s,border-color .14s}
    .hcard:hover{background:var(--input-bg);border-color:var(--border-s)}
    .hcard:active{transform:scale(.97)}
    .hcard.active{background:rgba(0,113,227,.1);border-color:rgba(0,113,227,.18)}
    .hcard-pre{font-size:13px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:-.15px}
    .hcard.active .hcard-pre{color:var(--blue-l)}
    .hcard-meta{font-size:11px;color:var(--fg3);margin-top:2px}
    .hcard-del{width:24px;height:24px;border:0;border-radius:6px;background:transparent;opacity:0;margin-left:auto;color:var(--fg3)}
    .hcard:hover .hcard-del{opacity:1}
    .hcard-del:active{background:rgba(255,59,48,.15);color:rgba(255,59,48,.8);transform:scale(.85)}
    .hcard-pin{display:none;width:11px;height:11px;fill:var(--blue-l)}
    .hcard.pinned .hcard-pin{display:inline-block}
    .h-empty{display:flex;flex-direction:column;align-items:center;gap:9px;padding:48px 16px;text-align:center}
    .h-empty svg{width:28px;height:28px;opacity:.45}
    .h-empty p{font-size:13px;line-height:1.5}
    #action-sheet{position:fixed;inset:0;z-index:9999;display:flex;flex-direction:column;justify-content:flex-end;pointer-events:none;opacity:0;transition:opacity .25s ease}
    #action-sheet[aria-hidden="false"]{pointer-events:auto;opacity:1}
    .as-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.45);backdrop-filter:blur(2px)}
    .as-container{padding:0 8px calc(8px + var(--sab)) 8px;transform:translateY(100%);transition:transform .32s cubic-bezier(.32,.72,0,1);display:flex;flex-direction:column;gap:8px}
    #action-sheet[aria-hidden="false"] .as-container{transform:translateY(0)}
    .as-group{background:rgba(28,28,30,.92);backdrop-filter:blur(40px) saturate(180%);border-radius:14px}
    @media (prefers-color-scheme: light){.as-group{background:rgba(242,242,242,.94)}}
    .as-title-block{padding:16px 16px 14px;text-align:center;border-bottom:.5px solid rgba(255,255,255,.08)}
    .as-title{font-size:13px;color:rgba(235,235,245,.85);font-weight:600}
    .as-message{font-size:13px;color:rgba(235,235,245,.55)}
    .as-option{width:100%;background:transparent;border:0;color:#0a84ff;font-size:20px;font-weight:400;padding:17px 16px;border-bottom:.5px solid rgba(255,255,255,.08);text-align:center}
    .as-option.destructive{color:#ff453a}
    .as-option.destructive.confirm{font-weight:600}
    .as-option:active{background:rgba(255,255,255,.08)}
    .as-cancel{background:rgba(44,44,46,.96);backdrop-filter:blur(40px) saturate(180%);border:0;border-radius:14px;color:#0a84ff;font-size:20px;font-weight:600;padding:17px 16px}
    @media (prefers-color-scheme: light){.as-cancel{background:rgba(255,255,255,.96)}}
    #content{flex:1;overflow:hidden;position:relative;z-index:1;touch-action:pan-y}
    #scroll-area{position:absolute;top:var(--sat);right:0;bottom:0;left:0;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior-y:contain;scrollbar-width:none;padding:12px 0 84px;scroll-padding-top:20px;scroll-padding-bottom:20px}
    #msg-list{display:flex;flex-direction:column;padding:0 14px;min-height:100%}
    .msg-group{display:flex;flex-direction:column;margin-bottom:14px;animation:bubbleSpring .45s cubic-bezier(.34,1.56,.64,1) both}
    @keyframes bubbleSpring{from{transform:translateY(14px) scale(.93);opacity:0}to{transform:none;opacity:1}}
    .msg-group.u{align-items:flex-end}
    .msg-group.a{align-items:flex-start}
    .bubble,.ai-bubble,.typing,.err-bbl{position:relative}
    .bubble{max-width:min(76vw,344px);padding:10px 14px;font-size:15px;line-height:1.5;letter-spacing:-.18px;border-radius:18px}
    .u .bubble{background:var(--user-bg);color:#fff;border-bottom-right-radius:4px;box-shadow:0 1px 8px rgba(0,113,227,.25),0 0 0 .5px rgba(0,113,227,.12);animation:bubbleIn .32s cubic-bezier(.34,1.3,.64,1)}
    .u .bubble::after{content:'';position:absolute;bottom:0;right:-6px;width:12px;height:12px;background:var(--user-bg);clip-path:polygon(0 0,100% 0,0 100%);transform:rotate(45deg);z-index:-1}
    @keyframes bubbleIn{from{opacity:0;transform:translateY(12px) scale(.93)}to{opacity:1;transform:none}}
    .ai-bubble{max-width:min(88vw,440px);padding:12px 15px;font-size:15px;line-height:1.55;letter-spacing:-.15px;border-radius:18px;border-bottom-left-radius:4px;background:var(--ai-bg);color:var(--ai-fg);backdrop-filter:blur(32px) saturate(160%);border:.5px solid var(--border);box-shadow:0 1px 3px rgba(0,0,0,.16);animation:aiBubbleIn .36s cubic-bezier(.34,1.15,.64,1) both}
    @keyframes aiBubbleIn{from{opacity:0;transform:translateX(-8px) scale(.97)}to{opacity:1;transform:none}}
    .ai-bubble::after{content:'';position:absolute;bottom:0;left:-6px;width:12px;height:12px;background:var(--ai-bg);clip-path:polygon(100% 0,0 0,100% 100%);transform:rotate(-45deg);z-index:-1}
    .img-in-msg{border-radius:14px;max-width:220px;max-height:185px;object-fit:cover;margin-bottom:6px;box-shadow:0 1px 6px rgba(0,0,0,.2)}
    .typing{display:flex;gap:4.5px;align-items:center;padding:11px 14px;border-radius:18px;border-bottom-left-radius:4px;background:var(--ai-bg);backdrop-filter:blur(32px) saturate(160%);border:.5px solid var(--border);max-width:58px;animation:bubbleIn .32s cubic-bezier(.34,1.3,.64,1) both}
    .td{width:6px;height:6px;border-radius:50%;background:var(--fg3);animation:td 1.1s cubic-bezier(.36,.11,.89,.32) infinite}
    .td:nth-child(2){animation-delay:.18s}
    .td:nth-child(3){animation-delay:.36s}
    @keyframes td{0%,100%{transform:translateY(0) scale(1);opacity:.25}25%{transform:translateY(-5px) scale(1.15);opacity:.9}50%{transform:translateY(0) scale(.95);opacity:.4}}
    .err-bbl{max-width:min(88vw,440px);padding:10px 14px;border-radius:14px;background:rgba(255,59,48,.1);border:.5px solid rgba(255,59,48,.18);font-size:13.5px;color:rgba(255,75,65,.82);line-height:1.45}
    .rcn-bar{margin:5px 14px;padding:8px 12px;background:rgba(255,159,0,.09);border:.5px solid rgba(255,159,0,.18);border-radius:10px;font-size:12px;color:rgba(255,175,30,.75)}
    .rcn-bar svg{animation:spin 1.1s linear infinite}
    .t-row{display:flex;gap:3px;margin-top:4px;padding:0 2px;opacity:0;transition:opacity .16s}
    .msg-group:hover .t-row,.msg-group:focus-within .t-row{opacity:1}
    .tact{border:0;border-radius:7px;padding:3px 9px;font-size:10.5px;color:var(--fg3);background:var(--input-bg)}
    .tact:active{color:var(--fg2);transform:scale(.92)}
    .btime{font-size:10px;color:var(--fg3);margin-top:4px;padding:0 3px}
    .md h1{font-size:17.5px;font-weight:700;letter-spacing:-.4px;margin:9px 0 5px}
    .md h2{font-size:15.5px;font-weight:600;letter-spacing:-.3px;margin:8px 0 4px}
    .md h3{font-size:14px;font-weight:600;margin:7px 0 3px}
    .md strong{font-weight:600}
    .md em{font-style:italic;opacity:.85}
    .md a{color:var(--blue-l);text-decoration:none}
    .md ul{padding:3px 0 3px 12px;list-style:none}
    .md li{padding:1px 0 1px 12px}
    .md li::before{content:'·';color:var(--fg3);font-size:14px}
    .md ol{padding:3px 0 3px 18px}
    .md p{margin:4px 0}
    .md hr{border:0;border-top:.5px solid var(--sep);margin:8px 0}
    .ic{display:inline;background:rgba(255,255,255,.09);border-radius:4px;padding:1px 5px;font-size:12.5px;font-family:'SF Mono',Menlo,Monaco,'Courier New',monospace;letter-spacing:.05px}
    @media (prefers-color-scheme: light){.ic{background:rgba(0,0,0,.07)}}
    .cb{border-radius:12px;overflow:hidden;margin:7px 0;box-shadow:0 3px 14px rgba(0,0,0,.32)}
    .cb-hdr{display:flex;align-items:center;justify-content:space-between;padding:7px 12px;background:#181820;border-bottom:.5px solid rgba(255,255,255,.05)}
    .cb-lang{font-size:10.5px;font-weight:500;color:rgba(255,255,255,.32);letter-spacing:.5px;text-transform:uppercase;font-family:'SF Mono',Menlo,monospace}
    .cb-copy{background:rgba(255,255,255,.08);border:0;border-radius:6px;padding:2px 9px;font-size:10.5px;color:rgba(255,255,255,.45)}
    .cb-copy:active{background:rgba(255,255,255,.14)}
    .cb pre code{font-family:'SF Mono',Menlo,Monaco,'Courier New',monospace;font-size:12px;line-height:1.65;padding:10px 13px;background:#14141a;overflow-x:auto;display:block}
    .md table{width:100%;border-collapse:collapse;margin:8px 0;font-size:13px;border-radius:10px;overflow:hidden;border:.5px solid var(--border)}
    .md thead{background:var(--input-bg)}
    .md th{padding:7px 11px;font-size:11px;font-weight:600;color:var(--fg2);letter-spacing:.3px;text-transform:uppercase;border-bottom:.5px solid var(--border);white-space:nowrap}
    .md td{padding:7px 11px;border-bottom:.5px solid var(--sep);vertical-align:top}
    .md tbody tr:nth-child(even) td{background:rgba(255,255,255,.025)}
    @media (prefers-color-scheme: light){.md tbody tr:nth-child(even) td{background:rgba(0,0,0,.025)}}
    .rc-wrap{max-width:min(88vw,440px);border-radius:14px;overflow:hidden;margin-bottom:6px;border:.5px solid var(--border-s);background:var(--rc-bg);backdrop-filter:blur(24px) saturate(140%)}
    .rc-head{display:flex;align-items:center;justify-content:space-between;padding:8px 13px;cursor:pointer;gap:8px}
    .rc-label{font-size:11px;font-weight:500;letter-spacing:.1px;color:var(--fg3)}
    .rc-dot{width:5px;height:5px;border-radius:50%;background:var(--fg3);animation:pulse 1.8s ease-in-out infinite}
    .rc-dot.done{animation:none;background:rgba(52,199,89,.55)}
    @keyframes pulse{0%,100%{opacity:.25}50%{opacity:.85}}
    .rc-dur{font-size:10.5px;color:var(--fg3)}
    .rc-chv{font-size:10px;color:var(--fg3);transition:transform .22s}
    .rc-chv.open{transform:rotate(180deg)}
    .rc-body{overflow:hidden;max-height:0;transition:max-height .36s cubic-bezier(.32,1.08,.5,1)}
    .rc-body.open{max-height:70vh;overflow-y:auto;scrollbar-width:none}
    .rc-text{font-size:12px;line-height:1.6;color:var(--fg3);padding:0 13px 11px;white-space:pre-wrap;font-style:italic}
    .rc-step{font-size:10.5px;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.7;font-style:italic;max-width:200px}
    .srch-wrap{max-width:min(88vw,440px);margin-bottom:6px}
    .srch-bar{display:flex;align-items:center;gap:8px;padding:8px 12px;background:rgba(0,113,227,.08);border:.5px solid rgba(0,113,227,.18);border-radius:12px}
    .srch-bar.done{background:rgba(52,199,89,.06);border-color:rgba(52,199,89,.18)}
    .srch-ico{width:13px;height:13px;animation:spin 1s linear infinite}
    .srch-bar.done .srch-ico{animation:none;fill:rgba(52,199,89,.8)}
    @keyframes spin{to{transform:rotate(360deg)}}
    .srch-q{font-size:12px;color:var(--blue-l);font-weight:500}
    .srch-bar.done .srch-q{color:rgba(52,199,89,.8)}
    .srch-count{font-size:10.5px;color:var(--fg3)}
    .src-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:5px}
    .src-chip{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;background:var(--input-bg);border:.5px solid var(--border-s);border-radius:20px;font-size:11px;color:var(--fg2);max-width:150px}
    .src-chip:active{transform:scale(.95)}
    .src-chip img{width:12px;height:12px;border-radius:2px}
    .ag-tool-wrap{max-width:min(88vw,440px);border-radius:12px;overflow:hidden;margin-bottom:5px;border:.5px solid var(--border-s);background:var(--rc-bg);backdrop-filter:blur(20px) saturate(130%)}
    .ag-tool-hdr{display:flex;align-items:center;gap:7px;padding:8px 12px;font-size:12px;color:var(--fg2)}
    .ag-tool-name{font-weight:500;color:var(--fg)}
    .ag-tool-detail{color:var(--fg3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    .ag-tool-body pre{padding:8px 10px;border-radius:8px;background:rgba(0,0,0,.25);font-size:11.5px;line-height:1.45;white-space:pre-wrap;word-break:break-all;max-height:200px;scrollbar-width:none}
    @media (prefers-color-scheme: light){.ag-tool-body pre{background:rgba(0,0,0,.04)}}
    .ag-file-badge{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:6px;font-size:11px;font-weight:500}
    .ag-file-badge.read{background:rgba(0,113,227,.1);color:rgba(0,113,227,.8)}
