    async function streamReq(prompt,images=[],txts=[]){currAb=new AbortController(); isStreaming=true; setTyping(true); els.btnSend.classList.add('stop'); els.btnSend.disabled=false; const payload={messages:[{role:'user',content:prompt}],images:images,session_id:csid,attachments:txts}; const endpoint=agentMode?'/api/agent':'/api/chat'; try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',...(token?{'Authorization':`Bearer ${token}`}:{})},body:JSON.stringify(payload),signal:currAb.signal}); if(!r.ok) throw new Error('HTTP '+r.status); const reader=r.body.getReader(); const dec=new TextDecoder(); let buf=''; while(true){const {done,value}=await reader.read(); if(done) break; buf+=dec.decode(value,{stream:true}); let idx; while((idx=buf.indexOf('\n\n'))>=0){const ev=buf.slice(0,idx).trim(); buf=buf.slice(idx+2); if(ev) processSSEEvent(ev)}} processSSEEvent('data: [DONE]');}catch(e){if(e.name!=='AbortError') toast('Hálózati hiba','err')}finally{isStreaming=false; setTyping(false); els.btnSend.classList.remove('stop'); els.btnSend.disabled=!els.ta.value.trim()&&!imgs.length&&!txts.length; save(); renderHistory(); scrollMsgs()}}
    function processSSEEvent(eventData){const line=eventData.split('\n').find(x=>x.startsWith('data:')); if(!line) return; const data=line.slice(5).trim(); if(data==='[DONE]'){streamMsg?.classList.add('done'); return} let obj; try{obj=JSON.parse(data)}catch{return}
      if(obj.type==='content'){if(!streamMsg){const g=mkGroup('a'); streamMsg=document.createElement('div'); streamMsg.className='ai-bubble md'; g.querySelector('.bubble-host').appendChild(streamMsg); els.msgList.appendChild(g)} streamTxt+=obj.text||''; if(!_mdRaf){_mdRaf=requestAnimationFrame(()=>{streamMsg.innerHTML=md(streamTxt); _mdRaf=null; scrollMsgs()})}}
      if(obj.type==='reasoning'){let wrap=$('.rc-wrap'); if(!wrap){wrap=document.createElement('div'); wrap.className='rc-wrap'; wrap.innerHTML='<div class="rc-head"><span class="rc-label">Gondolkodás</span><span class="rc-step">0</span><span class="rc-dur">0ms</span><span class="rc-chv">⌄</span></div><div class="rc-body"><div class="rc-text"></div></div>'; const g=mkGroup('a'); g.querySelector('.bubble-host').appendChild(wrap); els.msgList.appendChild(g); const st=wrap.querySelector('.rc-dur'); const t0=Date.now(); wrap._timer=setInterval(()=>st.textContent=(Date.now()-t0)+'ms',100); wrap.querySelector('.rc-head').onclick=()=>{wrap.querySelector('.rc-body').classList.toggle('open'); wrap.querySelector('.rc-chv').classList.toggle('open')}} wrap.querySelector('.rc-text').textContent+=(obj.text||'')}
      if(obj.type==='tool_call'){const w=document.createElement('div'); w.className='ag-tool-wrap'; w.innerHTML=`<div class="ag-tool-hdr"><span class="ag-tool-name">${esc(obj.name||'tool')}</span><span class="ag-tool-detail">${esc(obj.detail||'')}</span></div><div class="ag-tool-body"><pre>${esc(JSON.stringify(obj.args||{},null,2))}</pre></div>`; const g=mkGroup('a'); g.querySelector('.bubble-host').appendChild(w); els.msgList.appendChild(g)}
      if(obj.type==='search_start'){const w=document.createElement('div'); w.className='srch-wrap'; w.innerHTML=`<div class="srch-bar"><svg class="srch-ico" viewBox="0 0 24 24"><path fill="currentColor" d="M10 4a6 6 0 1 0 3.87 10.58l4.27 4.27a1 1 0 0 0 1.42-1.42l-4.27-4.27A6 6 0 0 0 10 4zm0 2a4 4 0 1 1 0 8 4 4 0 0 1 0-8z"/></svg><span class="srch-q">${esc(obj.query||'')}</span><span class="srch-count">keresés…</span></div>`; const g=mkGroup('a'); g.querySelector('.bubble-host').appendChild(w); els.msgList.appendChild(g)}
      if(obj.type==='search_results'){const bar=$('.srch-bar:not(.done)'); if(bar){bar.classList.add('done'); const c=bar.parentElement; c.insertAdjacentHTML('beforeend',`<div class="src-chips">${(obj.sources||[]).map(s=>`<span class="src-chip"><img src="https://www.google.com/s2/favicons?sz=64&domain_url=${encodeURIComponent(s.url||'')}">${esc((new URL(s.url)).hostname.replace(/^www\./,''))}</span>`).join('')}</div>`)}}
    }
    function updIbox(){els.imgStrip.innerHTML=''; imgs.forEach((src,i)=>{const d=document.createElement('div'); d.className='img-thumb'; d.innerHTML=`<img src="${src}"><button class="img-rm">×</button>`; d.querySelector('.img-rm').onclick=()=>{imgs.splice(i,1); updIbox()}; els.imgStrip.appendChild(d)}); txts.forEach((t,i)=>{const s=document.createElement('span'); s.className='file-chip'; s.textContent=t.name; els.imgStrip.appendChild(s)}); els.btnSend.disabled=!els.ta.value.trim()&&!imgs.length&&!txts.length}
    function autoResize(){els.ta.style.height='0px'; els.ta.style.height=Math.min(160,els.ta.scrollHeight)+'px';}
    function stop(){currAb?.abort(); setTyping(false); els.btnSend.classList.remove('stop'); els.btnSend.disabled=!els.ta.value.trim()&&!imgs.length&&!txts.length}
    async function handleFiles(files){for(const f of files){if(imgs.length<MAX_IMGS && /^image\//i.test(f.type)){const u=await imgToDataUrl(f); imgs.push(await compress(u,1024,.82))} else if(txts.length<MAX_TXTS){const ext=(f.name.split('.').pop()||'').toLowerCase(); if(TEXT_EXTS.includes(ext)){txts.push({name:f.name,text:await readFileAsText(f)})}}} updIbox()}
    function imgToDataUrl(file){return new Promise((res,rej)=>{const fr=new FileReader(); fr.onload=()=>res(fr.result); fr.onerror=rej; fr.readAsDataURL(file)})}
    function blobToDataUrl(blob){return new Promise((res,rej)=>{const fr=new FileReader(); fr.onload=()=>res(fr.result); fr.onerror=rej; fr.readAsDataURL(blob)})}
    async function compress(url,max=1024,q=.82){if(/^data:image\/gif/i.test(url)) return url; const img=new Image(); img.src=url; await img.decode().catch(()=>new Promise(r=>img.onload=r)); let w=img.naturalWidth,h=img.naturalHeight,ratio=Math.min(1,max/Math.max(w,h)); w=Math.round(w*ratio); h=Math.round(h*ratio); const c=document.createElement('canvas'); c.width=w; c.height=h; const ctx=c.getContext('2d'); ctx.drawImage(img,0,0,w,h); const mime=/data:image\/png|data:image\/webp/i.test(url)?'image/webp':'image/jpeg'; if(mime==='image/webp'&&c.toBlob) return await blobToDataUrl(await new Promise(r=>c.toBlob(r,mime,q))); return c.toDataURL(mime,q)}
    async function readFileAsText(file){const buf=await file.arrayBuffer(); const enc=detectTextEncoding(buf); return new TextDecoder(enc,{fatal:false,ignoreBOM:false}).decode(buf)}
    function detectTextEncoding(buffer){const b=new Uint8Array(buffer); if(b[0]===0xEF&&b[1]===0xBB&&b[2]===0xBF) return 'utf-8'; if(b[0]===0xFF&&b[1]===0xFE) return 'utf-16le'; if(b[0]===0xFE&&b[1]===0xFF) return 'utf-16be'; let i=0; while(i<b.length){if(b[i]<0x80){i++;continue} if((b[i]&0xE0)===0xC0&&i+1<b.length&&(b[i+1]&0xC0)===0x80){i+=2;continue} if((b[i]&0xF0)===0xE0&&i+2<b.length&&(b[i+1]&0xC0)===0x80&&(b[i+2]&0xC0)===0x80){i+=3;continue} if((b[i]&0xF8)===0xF0&&i+3<b.length&&(b[i+1]&0xC0)===0x80&&(b[i+2]&0xC0)===0x80&&(b[i+3]&0xC0)===0x80){i+=4;continue} return 'windows-1252'} return 'utf-8'}
    async function send(){const prompt=els.ta.value.trim(); if(!prompt && !imgs.length && !txts.length) return; navigator.vibrate?.(12); addMsgGroup('u',esc(prompt),imgs.slice()); const p=prompt; els.ta.value=''; els.ta.style.height='40px'; const attTxts=txts.slice(); imgs=[]; txts=[]; updIbox(); streamTxt=''; await streamReq(p,[],attTxts)}
    function addMsgGroup(side,html,imgsArr=[]){const g=document.createElement('div'); g.className='msg-group '+side; const host=document.createElement('div'); host.className='bubble-host'; g.appendChild(host); const b=document.createElement('div'); b.className=side==='u'?'bubble':'ai-bubble md'; b.innerHTML=html; host.appendChild(b); if(imgsArr.length) imgsArr.forEach(src=>{const im=document.createElement('img'); im.className='img-in-msg'; im.src=src; host.appendChild(im)}); const row=document.createElement('div'); row.className='t-row'; row.innerHTML='<button class="tact">Másolás</button><button class="tact">Törlés</button>'; const bt=document.createElement('div'); bt.className='btime'; bt.textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}); host.appendChild(row); host.appendChild(bt); els.msgList.appendChild(g); return b}
    async function init(){try{hmeta=JSON.parse(localStorage.getItem('ch_v4')||'{}')||{}; csid=localStorage.getItem('cs_v4')||null; deletedGroups=JSON.parse(localStorage.getItem('cgd_v1')||'[]')||[]; const me=await req('/api/auth/me'); if(me.status===401){showAuth(); return} const s=await req('/api/sessions'); if(s.ok){const j=await s.json(); (j.sessions||[]).forEach(x=>{hmeta[x.id]={...(hmeta[x.id]||{}),title:x.title||hmeta[x.id]?.title||'Chat',ts:x.ts||Date.now(),pinned:!!hmeta[x.id]?.pinned}}); save(); renderHistory()} if(csid) await restoreSid(csid); else {els.msgList.innerHTML='<div class="screen-empty">Kezdj egy új beszélgetést.</div>'; scrollMsgs()} }catch(e){showAuth()}}
    function showAuth(){els.authPanel.style.display='flex'; const can=!!window.PublicKeyCredential; els.authPasskey.classList.toggle('auth-hidden',!can)}
    function toggleAuthMode(){authMode=authMode==='login'?'register':'login'; els.authToggle.textContent=authMode==='login'?'Regisztráció':'Bejelentkezés'}
